const body = ($json.body) ? $json.body : $json;
const topic = body.topic || 'Majonoside-R2: Hoat chat doc quyen cua Sam Ngoc Linh Viet Nam';
const category = body.category || 'science';

const prompt = `Ban la chuyen gia duoc lieu hoc va content SEO cho thuong hieu TA Sam Ngoc Linh.

Viet bai blog chuan SEO bang tieng Viet, 2500+ tu, chu de: "${topic}".
Category: ${category}

Yeu cau bat buoc:
1. Cau truc: H1 tieu de -> H2 intro (150-200 tu) -> 5-7 H2 sections -> FAQs (6-8 Q&A) -> CTA
2. Moi H2 co 2-3 H3 sub-sections, bullet points 3-5 diem
3. TUYET DOI KHONG dung: dieu tri, chua khoi, cong dung (y hoc), het benh
4. Dung: ho tro, cai thien, giup duy tri, theo nghien cuu, du lieu cho thay
5. Cite peer-reviewed khi dung so lieu
6. Author: "Doi Ngu Nghien Cuu TA" - KHONG bia ten bac si
7. Cuoi bai: CTA "Kham pha san pham TA Sam Ngoc Linh"

Output PHAI la JSON hop le (khong markdown code block):
{"title_vi":"...","body_md":"## H2...\n\n### H3...\n\nbullet\n\n...","excerpt_vi":"150-160 ky tu, khong copy tieu de","slug_vi":"kebab-case-slug-60-chars","faq_list":[{"q":"?","a":"100-150 tu"}],"meta_description":"155-160 ky tu","compliance_check":"PASS"}`;

return [{ json: { topic, category, prompt } }];

const resp = $input.first().json;
const rawText = (resp?.candidates?.[0]?.content?.parts?.[0]?.text) || '';
const topic = $('Xay dung Prompt').first().json.topic;
const category = $('Xay dung Prompt').first().json.category;

let post = {};
try {
  let clean = rawText.trim();
  clean = clean.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  post = JSON.parse(clean);
} catch(e) {
  // Extract via regex fallback
  const titleMatch = rawText.match(/"title_vi"\s*:\s*"([^"]+)"/);
  const excerptMatch = rawText.match(/"excerpt_vi"\s*:\s*"([^"]+)"/);
  post = {
    title_vi: titleMatch ? titleMatch[1] : topic,
    body_md: rawText.substring(0, 5000),
    excerpt_vi: excerptMatch ? excerptMatch[1] : topic.substring(0, 155),
    slug_vi: '',
    faq_list: [],
    meta_description: topic.substring(0, 160),
    compliance_check: 'PARSE_FALLBACK'
  };
}

// Generate slug if missing
if (!post.slug_vi) {
  let s = (post.title_vi || topic).toLowerCase();
  const map = {'à':'a','á':'a','ả':'a','ã':'a','ạ':'a','ă':'a','ắ':'a','ặ':'a','ẳ':'a','ẵ':'a','ầ':'a','ấ':'a','ẩ':'a','ẫ':'a','ậ':'a','â':'a','è':'e','é':'e','ẻ':'e','ẽ':'e','ẹ':'e','ê':'e','ề':'e','ế':'e','ể':'e','ễ':'e','ệ':'e','ì':'i','í':'i','ỉ':'i','ĩ':'i','ị':'i','ò':'o','ó':'o','ỏ':'o','õ':'o','ọ':'o','ô':'o','ồ':'o','ố':'o','ổ':'o','ỗ':'o','ộ':'o','ơ':'o','ờ':'o','ớ':'o','ở':'o','ỡ':'o','ợ':'o','ù':'u','ú':'u','ủ':'u','ũ':'u','ụ':'u','ư':'u','ừ':'u','ứ':'u','ử':'u','ữ':'u','ự':'u','ỳ':'y','ý':'y','ỷ':'y','ỹ':'y','ỵ':'y','đ':'d'};
  s = s.split('').map(c => map[c] || c).join('');
  s = s.replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-{2,}/g,'-').replace(/^-|-$/g,'');
  post.slug_vi = s.substring(0, 60).replace(/-$/,'');
}

// Compliance check
const forbidden = ['điều trị','chữa khỏi','cong dung (y hoc)','het benh'];
const body = (post.body_md || '').toLowerCase();
const found = forbidden.filter(w => body.includes(w));
if (found.length) post.compliance_check = `FAIL: ${found.join(', ')}`;
if (!post.compliance_check) post.compliance_check = 'PASS';

return [{ json: { ...post, category, raw_topic: topic } }];
